-- ----------------------------
-- Table structure for t_as_attendance_record
-- ----------------------------
DROP TABLE IF EXISTS `t_as_attendance_record`;
CREATE TABLE `t_as_attendance_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `session_id` bigint(20) NOT NULL COMMENT '课次ID，对应 t_as_course_session.id',
  `target_type` tinyint(4) NOT NULL COMMENT '考勤对象类型：1学生 2教师',
  `student_id` bigint(20) NULL DEFAULT NULL COMMENT '学生ID，target_type=1时对应 t_as_student.id',
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学生学号，考勤流程展示冗余',
  `teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '教师ID，target_type=2时对应 t_as_teacher.id',
  `attendance_status` tinyint(4) NOT NULL COMMENT '考勤状态：1正常/到课 2迟到 3早退 4缺勤 5请假',
  `late_minutes` int(11) NULL DEFAULT 0 COMMENT '迟到分钟数，仅迟到时有值',
  `destination_type` tinyint(4) NULL DEFAULT NULL COMMENT '学生去向类型：1课程班 2回家 3培训机构 4留班 5行政课 6其他',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `record_source` tinyint(4) NULL DEFAULT 1 COMMENT '记录来源：1系统 2教师 3管理端 4请假联动',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `leave_id` bigint(20) NULL DEFAULT NULL COMMENT '请假id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_att_session_target`(`session_id`, `target_type`) USING BTREE,
  INDEX `idx_as_att_student`(`school_id`, `student_id`) USING BTREE,
  INDEX `idx_as_att_teacher`(`school_id`, `teacher_id`) USING BTREE,
  INDEX `idx_as_att_status`(`school_id`, `attendance_status`) USING BTREE,
  INDEX `idx_as_att_date`(`school_id`, `session_id`, `attendance_status`) USING BTREE,
  INDEX `idx_as_att_session_stu`(`session_id`, `student_id`) USING BTREE,
  INDEX `idx_att_session_student`(`session_id`, `student_id`, `is_valid`, `target_type`, `attendance_status`) USING BTREE,
  INDEX `idx_ar_school_valid_target_session`(`school_id`, `is_valid`, `target_type`, `session_id`, `attendance_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20734 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课次考勤明细' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_attendance_record
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_business_attachment
-- ----------------------------
DROP TABLE IF EXISTS `t_as_business_attachment`;
CREATE TABLE `t_as_business_attachment`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `biz_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型，如 LEAVE_REQUEST/COURSE_FEEDBACK/PATROL_RECORD/RECTIFICATION_ORDER/LOGISTICS_SAFETY',
  `biz_id` bigint(20) NOT NULL COMMENT '业务主键ID',
  `file_id` bigint(20) NOT NULL COMMENT '文件ID，对应 t_base_file.id',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_attach_biz`(`biz_type`, `biz_id`) USING BTREE,
  INDEX `idx_as_attach_file`(`file_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后业务附件关联' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_business_attachment
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_course_category
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_category`;
CREATE TABLE `t_as_course_category`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类别编码，同一学校+类型内唯一',
  `category_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类别名称',
  `enabled_status` tinyint(4) NULL DEFAULT 1 COMMENT '启用状态：1启用 0停用',
  `sort_no` int(11) NULL DEFAULT 0 COMMENT '排序号，值越小越靠前',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '父类别id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_course_category_code`(`school_id`, `category_code`) USING BTREE,
  INDEX `idx_as_course_category_status`(`school_id`, `enabled_status`) USING BTREE,
  INDEX `t_as_course_category_name`(`school_id`, `category_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 92 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后类别/学习模块' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_course_category
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_course_class
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_class`;
CREATE TABLE `t_as_course_class`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `service_id` bigint(20) NOT NULL COMMENT '所属服务ID，对应 t_as_service.id',
  `course_class_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '课程班编码',
  `course_class_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程班名称',
  `category_id` bigint(20) NULL DEFAULT NULL COMMENT '课后类别ID，对应 t_as_course_category.id',
  `module_id` bigint(20) NULL DEFAULT NULL COMMENT '学习模块ID，对应 t_as_course_category.id',
  `enroll_type` tinyint(4) NULL DEFAULT 1 COMMENT '报名方式：1公开报名 2邀请报名 3行政班安排',
  `applicable_class_ids` json NULL COMMENT '行政班安排适用班级ID集合，JSON数组',
  `applicable_grade_ids` json NULL COMMENT '适用年级ID集合',
  `parent_confirm_required` tinyint(4) NULL DEFAULT 0 COMMENT '邀请报名时是否需要家长确认：0否 1是',
  `gender_requirement` tinyint(4) NULL DEFAULT 0 COMMENT '公开报名性别要求：0不限 1男 2女',
  `capacity` int(11) NULL DEFAULT 0 COMMENT '课程班容量上限',
  `enrolled_count` int(11) NULL DEFAULT 0 COMMENT '已报名人数',
  `teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '授课教师ID，对应 t_as_teacher.id',
  `place_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上课地点/教室名称',
  `place_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '教室ID，多个用英文逗号分隔，如：1,2,3',
  `intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '课程简介',
  `class_status` tinyint(4) NULL DEFAULT 1 COMMENT '课程班状态：1未开始 2进行中 3已结束 4停用',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `course_file` bigint(20) NULL DEFAULT NULL COMMENT '课程封面图片',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_course_class_service`(`service_id`) USING BTREE,
  INDEX `idx_as_course_class_teacher`(`school_id`, `teacher_id`) USING BTREE,
  INDEX `idx_as_course_class_category`(`school_id`, `category_id`) USING BTREE,
  INDEX `idx_as_course_class_module`(`school_id`, `module_id`) USING BTREE,
  INDEX `idx_as_course_class_status`(`school_id`, `class_status`) USING BTREE,
  INDEX `idx_as_course_class_enroll_type`(`school_id`, `enroll_type`) USING BTREE,
  INDEX `idx_cc_service`(`is_valid`, `service_id`) USING BTREE,
  INDEX `idx_cc_school_valid_service`(`school_id`, `is_valid`, `service_id`, `category_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2876 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务课程班' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_course_class
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_course_grade_quota
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_grade_quota`;
CREATE TABLE `t_as_course_grade_quota`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL,
  `course_class_id` bigint(20) NOT NULL,
  `grade_id` bigint(20) NOT NULL,
  `capacity` int(11) NOT NULL,
  `enrolled_count` int(11) NOT NULL DEFAULT 0,
  `create_user` bigint(20) NULL DEFAULT NULL,
  `update_user` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `is_valid` tinyint(4) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_course_grade`(`course_class_id`, `grade_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '公开课程班年级限额' ROW_FORMAT = DYNAMIC;

