-- ----------------------------
-- Table structure for t_as_course_invite
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_invite`;
CREATE TABLE `t_as_course_invite`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `course_class_id` bigint(20) NOT NULL COMMENT '课程班ID，对应 t_as_course_class.id',
  `teacher_id` bigint(20) NOT NULL COMMENT '发起邀请教师ID，对应 t_as_teacher.id',
  `invite_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '邀请码，同一学校内唯一',
  `invite_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '邀请链接URL',
  `invite_qr_file_id` bigint(20) NULL DEFAULT NULL COMMENT '二维码图片文件ID，对应 t_base_file.id',
  `invite_student_ids` json NULL COMMENT '确认邀请时选中的学生ID集合，JSON数组',
  `parent_confirm_required` tinyint(4) NULL DEFAULT 0 COMMENT '是否需要家长确认报名：0否 1是，冗余课程班配置',
  `selected_count` int(11) NULL DEFAULT 0 COMMENT '已选中学生人数',
  `invite_status` tinyint(4) NULL DEFAULT 1 COMMENT '邀请状态：1有效 2失效',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '邀请过期时间',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_course_invite_code`(`school_id`, `invite_code`) USING BTREE,
  INDEX `idx_as_course_invite_class`(`school_id`, `course_class_id`) USING BTREE,
  INDEX `idx_as_course_invite_teacher`(`school_id`, `teacher_id`) USING BTREE,
  INDEX `idx_as_course_invite_status`(`school_id`, `invite_status`) USING BTREE,
  INDEX `idx_as_invite_course_latest`(`course_class_id`, `is_valid`, `invite_status`, `id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 130 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课程邀请链接/二维码批次' ROW_FORMAT = DYNAMIC;

