-- Records of t_as_course_invite
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_course_quota_member
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_quota_member`;
CREATE TABLE `t_as_course_quota_member`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `course_class_id` bigint(20) NOT NULL,
  `student_id` bigint(20) NOT NULL,
  `term_id` bigint(20) NULL DEFAULT NULL,
  `grade_id` bigint(20) NULL DEFAULT NULL COMMENT '占位时年级，退课不能改用当前年级',
  `occupied` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0已释放 1已占用 ',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_course_student`(`course_class_id`, `student_id`) USING BTREE,
  INDEX `idx_course_grade_occupied`(`course_class_id`, `grade_id`, `occupied`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '公开课程班学生名额占用' ROW_FORMAT = DYNAMIC;

