-- ----------------------------
-- Table structure for t_as_course_schedule_rule
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_schedule_rule`;
CREATE TABLE `t_as_course_schedule_rule`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL COMMENT '所属学校',
  `service_id` bigint(20) NOT NULL COMMENT '课后服务ID',
  `course_class_id` bigint(20) NOT NULL COMMENT '课程班ID',
  `rule_type` tinyint(4) NOT NULL COMMENT '规则类型：1周期 2自定义日期',
  `week_days_json` json NULL COMMENT '周期规则星期集合，如[1,3,5]',
  `session_date` date NULL DEFAULT NULL COMMENT '自定义日期',
  `schedule_period_id` bigint(20) NULL DEFAULT NULL COMMENT '来源课后时间段',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `place_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规则覆盖地点，空时使用课程班地点',
  `teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '规则覆盖教师，空时使用课程班教师',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '是否有效：1有效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_schedule_rule_class`(`course_class_id`) USING BTREE,
  INDEX `idx_as_schedule_rule_service`(`service_id`) USING BTREE,
  INDEX `idx_as_schedule_rule_school`(`school_id`) USING BTREE,
  INDEX `idx_as_schedule_rule_class_valid_type_time`(`course_class_id`, `is_valid`, `rule_type`, `session_date`, `start_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3269 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课程班排课规则' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_course_schedule_rule
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_course_session
-- ----------------------------
DROP TABLE IF EXISTS `t_as_course_session`;
CREATE TABLE `t_as_course_session`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `course_class_id` bigint(20) NOT NULL COMMENT '所属课程班ID，对应 t_as_course_class.id',
  `session_date` date NOT NULL COMMENT '上课日期',
  `week_day` tinyint(4) NULL DEFAULT NULL COMMENT '星期几：1周一至7周日',
  `schedule_period_id` bigint(20) NULL DEFAULT NULL COMMENT '来源作息/课后时间段ID，对应 t_as_schedule_period.id',
  `start_time` time NOT NULL COMMENT '上课开始时间',
  `end_time` time NOT NULL COMMENT '上课结束时间',
  `session_start_date` datetime NULL DEFAULT NULL COMMENT '课次开始日期时间（session_date + start_time 组合）',
  `session_end_date` datetime NULL DEFAULT NULL COMMENT '课次结束日期时间（session_date + end_time 组合）',
  `teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '授课教师ID，对应 t_as_teacher.id',
  `place_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上课地点/教室名称',
  `session_status` tinyint(4) NULL DEFAULT 0 COMMENT '课次状态：0未开始 1进行中 2已完成 3取消',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `original_teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '调课前原教师ID',
  `adjust_request_id` bigint(20) NULL DEFAULT NULL COMMENT '生效调课申请ID',
  `adjust_status` tinyint(4) NULL DEFAULT 0 COMMENT '调课状态：0未调课 1已调课',
  `is_operate_attend` int(11) NULL DEFAULT 0 COMMENT '是否操作考勤点到 0-否 1-是',
  `operate_attend_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作考勤点到时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_session_class_date`(`course_class_id`, `session_date`) USING BTREE,
  INDEX `idx_as_session_teacher_date`(`teacher_id`, `session_date`) USING BTREE,
  INDEX `idx_as_session_status`(`school_id`, `session_status`) USING BTREE,
  INDEX `idx_as_session_date_range`(`school_id`, `session_date`) USING BTREE,
  INDEX `idx_as_session_adjust`(`school_id`, `adjust_request_id`) USING BTREE,
  INDEX `idx_as_session_teacher_time`(`school_id`, `teacher_id`, `session_date`, `start_time`, `end_time`) USING BTREE,
  INDEX `idx_session_cc`(`course_class_id`, `is_valid`) USING BTREE,
  INDEX `idx_cs_school_valid_status_date`(`school_id`, `is_valid`, `session_status`, `session_date`, `course_class_id`) USING BTREE,
  INDEX `idx_cs_valid_startdate`(`id`, `is_valid`, `session_start_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18606 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务课次' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_course_session
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_enrollment
-- ----------------------------
DROP TABLE IF EXISTS `t_as_enrollment`;
CREATE TABLE `t_as_enrollment`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `service_id` bigint(20) NOT NULL COMMENT '所属服务ID，对应 t_as_service.id',
  `course_class_id` bigint(20) NULL DEFAULT NULL COMMENT '课程班ID，对应 t_as_course_class.id',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID，对应 t_as_student.id',
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学生学号，选课流程展示冗余',
  `session_id` bigint(20) NULL DEFAULT NULL COMMENT '课次id,t_as_course_session.id',
  `enroll_source` tinyint(4) NULL DEFAULT 1 COMMENT '报名来源：1家长公开报名 2教师邀请 3行政班安排',
  `enroll_status` tinyint(4) NULL DEFAULT 0 COMMENT '报名状态：0待确认 1已报名 2已取消 3已分配 4未分配',
  `invite_id` bigint(20) NULL DEFAULT NULL COMMENT '来源邀请批次ID，对应 t_as_course_invite.id',
  `parent_confirm_required` tinyint(4) NULL DEFAULT 0 COMMENT '是否需要家长确认：0否 1是',
  `guardian_confirm_user_id` bigint(20) NULL DEFAULT NULL COMMENT '家长确认账号ID，对应 t_base_user.id',
  `guardian_confirm_time` datetime NULL DEFAULT NULL COMMENT '家长确认时间',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `operator_type` tinyint(4) NULL DEFAULT NULL COMMENT '最近操作来源：1家长 2教师 3管理员 4系统',
  `operator_user_id` bigint(20) NULL DEFAULT NULL COMMENT '最近操作用户ID',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近操作人展示名称',
  `enroll_time` datetime NULL DEFAULT NULL COMMENT '报名/分配生效时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `cancel_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取消原因',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报名/分配备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_enroll_service_student_session`(`school_id`, `service_id`, `student_id`, `session_id`) USING BTREE,
  INDEX `idx_as_enroll_student`(`school_id`, `student_id`) USING BTREE,
  INDEX `idx_as_enroll_class`(`course_class_id`, `enroll_status`) USING BTREE,
  INDEX `idx_as_enroll_invite`(`school_id`, `invite_id`) USING BTREE,
  INDEX `idx_as_enroll_service`(`school_id`, `service_id`) USING BTREE,
  INDEX `idx_as_enroll_status`(`school_id`, `enroll_status`) USING BTREE,
  INDEX `idx_as_enroll_source`(`school_id`, `enroll_source`) USING BTREE,
  INDEX `idx_as_enroll_service_status`(`school_id`, `service_id`, `enroll_status`) USING BTREE,
  INDEX `idx_as_enroll_service_student_status`(`school_id`, `service_id`, `student_id`, `enroll_status`) USING BTREE,
  INDEX `idx_as_enroll_session`(`session_id`) USING BTREE,
  INDEX `idx_as_enroll_headteacher_assigned`(`school_id`, `operator_user_id`, `enroll_status`, `enroll_source`, `is_valid`, `student_id`, `service_id`, `course_class_id`, `session_id`) USING BTREE,
  INDEX `idx_as_enroll_invite_student`(`school_id`, `invite_id`, `student_id`, `is_valid`, `id`) USING BTREE,
  INDEX `idx_as_enroll_course_student`(`school_id`, `course_class_id`, `student_id`, `is_valid`, `id`) USING BTREE,
  INDEX `idx_as_enroll_invite_page_course`(`course_class_id`, `student_id`, `is_valid`, `session_id`, `enroll_status`, `enroll_source`, `id`) USING BTREE,
  INDEX `idx_as_enroll_invite_page_service`(`school_id`, `service_id`, `student_id`, `is_valid`, `session_id`, `enroll_status`) USING BTREE,
  INDEX `idx_as_enroll_invite_page_active`(`school_id`, `student_id`, `is_valid`, `session_id`, `course_class_id`, `enroll_status`, `update_time`) USING BTREE,
  INDEX `idx_as_enroll_invite_page_student_latest`(`student_id`, `is_valid`, `session_id`, `update_time`) USING BTREE,
  INDEX `idx_as_enroll_headteacher_all`(`school_id`, `is_valid`, `student_id`, `service_id`, `id`) USING BTREE,
  INDEX `idx_enrollment_school_valid_course`(`school_id`, `is_valid`, `course_class_id`, `student_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10000023 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生选课/报名记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_enrollment
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_enrollment_log
-- ----------------------------
DROP TABLE IF EXISTS `t_as_enrollment_log`;
CREATE TABLE `t_as_enrollment_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL,
  `enrollment_id` bigint(20) NOT NULL,
  `service_id` bigint(20) NOT NULL,
  `student_id` bigint(20) NOT NULL,
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `before_course_class_id` bigint(20) NULL DEFAULT NULL,
  `after_course_class_id` bigint(20) NULL DEFAULT NULL,
  `before_enroll_status` tinyint(4) NULL DEFAULT NULL,
  `after_enroll_status` tinyint(4) NULL DEFAULT NULL,
  `action_type` tinyint(4) NOT NULL COMMENT '1初始化 2公开报名 3邀请报名 4邀请确认 5邀请拒绝 6行政班安排 7手动分配 8改课 9取消',
  `operator_type` tinyint(4) NULL DEFAULT NULL COMMENT '1家长 2教师 3管理员 4系统',
  `operator_user_id` bigint(20) NULL DEFAULT NULL,
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `is_valid` tinyint(4) NULL DEFAULT 1,
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_enroll_log_enrollment`(`enrollment_id`) USING BTREE,
  INDEX `idx_as_enroll_log_student`(`school_id`, `service_id`, `student_id`) USING BTREE,
  INDEX `idx_as_enroll_log_action`(`school_id`, `action_type`, `create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 79657 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生选课操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_enrollment_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_guardian_student
-- ----------------------------
DROP TABLE IF EXISTS `t_as_guardian_student`;
CREATE TABLE `t_as_guardian_student`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `guardian_user_id` bigint(20) NULL DEFAULT NULL COMMENT '家长账号ID，对应 t_base_user.id',
  `student_identity_id` bigint(20) NOT NULL COMMENT '学生稳定身份编号',
  `parent_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '家长姓名',
  `relation_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '与学生的亲属关系，如妈妈/爸爸/爷爷等',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '家长手机号',
  `bind_status` tinyint(4) NULL DEFAULT 1 COMMENT '绑定状态：1有效 2解绑',
  `create_user` bigint(20) NOT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `phone_info` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所有的手机号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_guardian_school_identity`(`school_id`, `guardian_user_id`, `student_identity_id`) USING BTREE,
  INDEX `idx_as_guardian_bind_status`(`school_id`, `bind_status`) USING BTREE,
  INDEX `idx_as_guardian_school_identity`(`school_id`, `student_identity_id`, `bind_status`, `is_valid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5490 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '家长学生监护关系' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_guardian_student
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_schedule_period
-- ----------------------------
DROP TABLE IF EXISTS `t_as_schedule_period`;
CREATE TABLE `t_as_schedule_period`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `template_id` bigint(20) NOT NULL COMMENT '所属方案ID，对应 t_as_schedule_template.id',
  `period_type` tinyint(4) NOT NULL COMMENT '时段类型：1普通节次 2课后时间段',
  `day_of_week` tinyint(4) NULL DEFAULT NULL COMMENT '星期几：1周一至7周日，课后时间可为空',
  `day_scope_json` json NULL COMMENT '课后时间频率，如周一至周五的JSON数组',
  `grade_scope_json` json NULL COMMENT '适用年级ID集合的JSON数组',
  `section_no` int(11) NULL DEFAULT NULL COMMENT '节次序号，如第一节至第八节',
  `section_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节次名称，如第一节/课后服务一',
  `time_block` tinyint(4) NULL DEFAULT NULL COMMENT '普通节次时间段：1上午 2下午',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `sort_no` int(11) NULL DEFAULT 0 COMMENT '排序号，值越小越靠前',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_schedule_period_template`(`template_id`, `sort_no`) USING BTREE,
  INDEX `idx_as_schedule_period_time`(`school_id`, `period_type`, `day_of_week`) USING BTREE,
  INDEX `idx_t_as_schedule_period_schid_sno`(`school_id`, `section_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 456 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '作息节次/课后时间段' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_schedule_period
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_schedule_template
-- ----------------------------
DROP TABLE IF EXISTS `t_as_schedule_template`;
CREATE TABLE `t_as_schedule_template`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `template_type` tinyint(4) NOT NULL COMMENT '方案类型：1作息管理 2课后时间管理',
  `template_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '方案名称',
  `enabled_status` tinyint(4) NULL DEFAULT 1 COMMENT '启用状态：1启用 0停用',
  `school_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学校名称，原型详情展示冗余',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_schedule_template`(`school_id`, `template_type`, `enabled_status`) USING BTREE,
  INDEX `t_as_schedule_template_name`(`template_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '作息/课后时间方案' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_schedule_template
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_service
-- ----------------------------
DROP TABLE IF EXISTS `t_as_service`;
CREATE TABLE `t_as_service`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `service_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务编码，同一学校内唯一',
  `service_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程活动名称',
  `term_id` bigint(20) NOT NULL COMMENT '所属学期，对应 t_educl_term.id',
  `enroll_start_time` datetime NULL DEFAULT NULL COMMENT '报名开始时间',
  `enroll_end_time` datetime NULL DEFAULT NULL COMMENT '报名结束时间',
  `course_start_date` date NULL DEFAULT NULL COMMENT '开课开始日期',
  `course_end_date` date NULL DEFAULT NULL COMMENT '开课结束日期',
  `after_school_time_template_id` bigint(20) NULL DEFAULT NULL COMMENT '课后时间管理方案ID，对应 t_as_schedule_template.id',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人账号ID，对应 t_base_user.id',
  `service_status` tinyint(4) NULL DEFAULT 0 COMMENT '服务状态：0未发布 1报名中 2进行中 3已结束',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `grade_scope_json` json NULL COMMENT '服务适用年级ID集合',
  `class_scope_json` json NULL COMMENT '服务适用行政班ID集合',
  `selection_init_status` tinyint(4) NULL DEFAULT 0 COMMENT '选课初始化状态：0未初始化 1初始化中 2已初始化',
  `selection_init_time` datetime NULL DEFAULT NULL COMMENT '选课初始化完成时间',
  `source_service_id` bigint(20) NULL DEFAULT NULL COMMENT '复制来源课后服务编号，手工新增为空',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_service_code`(`school_id`, `service_code`) USING BTREE,
  INDEX `idx_as_service_status`(`school_id`, `service_status`) USING BTREE,
  INDEX `idx_as_service_term`(`school_id`, `term_id`) USING BTREE,
  INDEX `idx_as_service_enroll_time`(`school_id`, `enroll_start_time`, `enroll_end_time`) USING BTREE,
  INDEX `idx_as_service_source`(`source_service_id`) USING BTREE,
  INDEX `idx_svc_term`(`term_id`, `school_id`, `is_valid`) USING BTREE,
  INDEX `idx_service_valid_term`(`is_valid`, `term_id`, `id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1403 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务活动' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_service
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_service_student_notice
-- ----------------------------
DROP TABLE IF EXISTS `t_as_service_student_notice`;
CREATE TABLE `t_as_service_student_notice`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL COMMENT '学校编号',
  `service_id` bigint(20) NOT NULL COMMENT '课后服务编号',
  `student_identity_id` bigint(20) NOT NULL COMMENT '学生稳定身份编号',
  `guardian_user_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际接收提醒的家长用户编号集合',
  `notice_type` tinyint(4) NOT NULL COMMENT '提醒类型：1报名开放期补发提醒',
  `create_user` bigint(20) NULL DEFAULT NULL,
  `update_user` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_service_student_notice`(`service_id`, `student_identity_id`, `notice_type`) USING BTREE,
  INDEX `idx_as_service_student_notice_school`(`school_id`, `service_id`, `is_valid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 83 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务学生提醒去重记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_service_student_notice
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_student
-- ----------------------------
DROP TABLE IF EXISTS `t_as_student`;
CREATE TABLE `t_as_student`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `student_identity_id` bigint(20) NULL DEFAULT NULL COMMENT '学生稳定身份编号',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `term_id` int(11) NOT NULL COMMENT '学期编号',
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '学号，同一学校内唯一',
  `student_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生姓名',
  `gender` tinyint(4) NULL DEFAULT NULL COMMENT '性别：0男 1女',
  `id_card` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证件号码',
  `avatar_file_id` bigint(20) NULL DEFAULT NULL COMMENT '头像文件ID，对应 t_base_file.id',
  `grade_id` bigint(20) NULL DEFAULT NULL COMMENT '所属年级，对应 t_educl_grade.id',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '所属行政班，对应 t_educl_class.id',
  `school_roll_status` tinyint(4) NULL DEFAULT 1 COMMENT '学籍状态：1在籍 2毕业 3休学 4转学',
  `register_status` tinyint(4) NULL DEFAULT 0 COMMENT '审核状态：0待注册 1已通过 2已驳回 3待审核',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '学生账号ID，对应 t_base_user.id，主要由家长绑定',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `audit_remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `graduation_year` int(11) NULL DEFAULT NULL COMMENT '毕业年份',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_student_school_term_no`(`school_id`, `term_id`, `student_no`) USING BTREE,
  UNIQUE INDEX `uk_as_student_school_term_identity`(`school_id`, `term_id`, `student_identity_id`) USING BTREE,
  INDEX `idx_as_student_class`(`school_id`, `grade_id`, `class_id`) USING BTREE,
  INDEX `idx_as_student_user`(`user_id`) USING BTREE,
  INDEX `idx_as_student_roll_status`(`school_id`, `school_roll_status`) USING BTREE,
  INDEX `idx_as_student_register_status`(`school_id`, `register_status`) USING BTREE,
  INDEX `idx_as_student_invite_class`(`school_id`, `is_valid`, `register_status`, `class_id`) USING BTREE,
  INDEX `idx_as_student_identity`(`school_id`, `student_identity_id`, `term_id`, `is_valid`) USING BTREE,
  INDEX `idx_student_class_term`(`class_id`, `term_id`, `school_id`, `is_valid`, `register_status`) USING BTREE,
  INDEX `idx_student_school_term_valid`(`school_id`, `term_id`, `is_valid`, `register_status`, `school_roll_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6024 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务学生档案' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_student
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_student_adjust_log
-- ----------------------------
DROP TABLE IF EXISTS `t_as_student_adjust_log`;
CREATE TABLE `t_as_student_adjust_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL,
  `request_id` bigint(20) NOT NULL,
  `action_type` tinyint(4) NOT NULL COMMENT '1提交 2撤回 3通过 4驳回',
  `before_status` tinyint(4) NULL DEFAULT NULL,
  `after_status` tinyint(4) NULL DEFAULT NULL,
  `operator_type` tinyint(4) NULL DEFAULT NULL COMMENT '1班主任 2管理员 3系统',
  `operator_user_id` bigint(20) NULL DEFAULT NULL,
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `snapshot_json` json NULL COMMENT '操作快照',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `is_valid` tinyint(4) NULL DEFAULT 1,
  `create_user` bigint(20) NULL DEFAULT NULL,
  `update_user` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_student_adjust_log_request`(`request_id`) USING BTREE,
  INDEX `idx_as_student_adjust_log_action`(`school_id`, `action_type`, `create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 200 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生调课操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_student_adjust_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_student_destination
-- ----------------------------
DROP TABLE IF EXISTS `t_as_student_destination`;
CREATE TABLE `t_as_student_destination`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `service_id` bigint(20) NULL DEFAULT NULL COMMENT '所属服务ID，对应 t_as_service.id',
  `session_id` bigint(20) NULL DEFAULT NULL COMMENT '课次id,t_as_course_session.id',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID，对应 t_as_student.id',
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学生学号，去向/选课流程展示冗余',
  `destination_type` tinyint(4) NOT NULL COMMENT '去向类型：1课程班 2回家 3培训机构 4留班 5行政课 6其他',
  `course_class_id` bigint(20) NULL DEFAULT NULL COMMENT '课程班ID，去向为课程班时对应 t_as_course_class.id',
  `destination_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '去向名称，如培训机构名称',
  `assign_user_id` bigint(20) NULL DEFAULT NULL COMMENT '分配人账号ID，对应 t_base_user.id',
  `assign_time` datetime NULL DEFAULT NULL COMMENT '分配时间',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_dest_service_student_session`(`school_id`, `service_id`, `student_id`, `session_id`) USING BTREE,
  INDEX `idx_as_dest_student`(`school_id`, `student_id`) USING BTREE,
  INDEX `idx_as_dest_class`(`course_class_id`) USING BTREE,
  INDEX `idx_as_dest_service_type`(`school_id`, `service_id`, `destination_type`) USING BTREE,
  INDEX `idx_as_dest_session`(`session_id`) USING BTREE,
  INDEX `idx_dest_student`(`student_id`, `school_id`, `is_valid`) USING BTREE,
  INDEX `idx_dest_student_valid_type`(`student_id`, `is_valid`, `destination_type`, `session_id`) USING BTREE,
  INDEX `idx_sd_student_valid_session`(`student_id`, `is_valid`, `session_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 360670 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生课后去向分配' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_student_destination
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_student_identity
-- ----------------------------
DROP TABLE IF EXISTS `t_as_student_identity`;
CREATE TABLE `t_as_student_identity`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL COMMENT '学校编号',
  `enrollment_year` int(11) NULL DEFAULT NULL COMMENT '一年级基准入学年份，用于计算目标学年年级',
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '当前规范学号',
  `student_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生姓名',
  `gender` tinyint(4) NULL DEFAULT NULL COMMENT '0男 1女',
  `id_card` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `avatar_file_id` bigint(20) NULL DEFAULT NULL COMMENT '头像文件编号',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '学生账号编号',
  `create_user` bigint(20) NULL DEFAULT NULL,
  `update_user` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_student_identity_school_no`(`school_id`, `student_no`) USING BTREE,
  INDEX `idx_as_student_identity_user`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5283 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务学生稳定身份' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_student_identity
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_student_no_change_log
-- ----------------------------
DROP TABLE IF EXISTS `t_as_student_no_change_log`;
CREATE TABLE `t_as_student_no_change_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL COMMENT '学校编号',
  `student_identity_id` bigint(20) NOT NULL COMMENT '学生稳定身份编号',
  `old_student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '修改前学号',
  `new_student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '修改后学号',
  `change_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '修改原因',
  `create_user` bigint(20) NULL DEFAULT NULL,
  `update_user` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_as_student_no_log_old_no`(`school_id`, `old_student_no`) USING BTREE,
  INDEX `idx_as_student_no_log_identity`(`school_id`, `student_identity_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生学号纠错审计记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_student_no_change_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_student_term_change_log
-- ----------------------------
DROP TABLE IF EXISTS `t_as_student_term_change_log`;
CREATE TABLE `t_as_student_term_change_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) NOT NULL COMMENT '学校编号',
  `term_id` bigint(20) NOT NULL COMMENT '学期编号',
  `student_id` bigint(20) NOT NULL COMMENT '学生学期快照编号',
  `student_identity_id` bigint(20) NOT NULL COMMENT '学生稳定身份编号',
  `effective_time` datetime NOT NULL COMMENT '变更生效时间',
  `old_grade_id` bigint(20) NULL DEFAULT NULL COMMENT '变更前年级编号',
  `new_grade_id` bigint(20) NULL DEFAULT NULL COMMENT '变更后年级编号',
  `old_class_id` bigint(20) NULL DEFAULT NULL COMMENT '变更前班级编号',
  `new_class_id` bigint(20) NULL DEFAULT NULL COMMENT '变更后班级编号',
  `old_school_roll_status` tinyint(4) NULL DEFAULT NULL COMMENT '变更前学籍状态',
  `new_school_roll_status` tinyint(4) NULL DEFAULT NULL COMMENT '变更后学籍状态',
  `change_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '变更原因',
  `apply_status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '生效状态：0待生效，1已生效，2生效失败，3正在生效',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '实际生效时间',
  `failure_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生效失败原因',
  `create_user` bigint(20) NULL DEFAULT NULL,
  `update_user` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_valid` tinyint(4) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_student_term_change_student`(`school_id`, `term_id`, `student_id`, `effective_time`) USING BTREE,
  INDEX `idx_as_student_term_change_identity`(`school_id`, `student_identity_id`, `effective_time`) USING BTREE,
  INDEX `idx_as_student_term_change_pending`(`apply_status`, `effective_time`, `is_valid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生学期内资料变更记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_student_term_change_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_subject
-- ----------------------------
DROP TABLE IF EXISTS `t_as_subject`;
CREATE TABLE `t_as_subject`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '学科ID',
  `subject_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学科编码',
  `subject_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学科名称',
  `subject_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学科描述',
  `grade_id` bigint(20) NOT NULL COMMENT '年级id',
  `school_id` bigint(20) NOT NULL COMMENT '年级id',
  `enabled` tinyint(4) NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` bigint(20) NOT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_enabled`(`enabled`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '学科管理表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_subject
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_teacher
-- ----------------------------
DROP TABLE IF EXISTS `t_as_teacher`;
CREATE TABLE `t_as_teacher`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '教师账号ID，对应 t_base_user.id',
  `teacher_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '教师工号，同一学校内唯一',
  `teacher_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '教师姓名',
  `gender` tinyint(4) NULL DEFAULT NULL COMMENT '性别：0男 1女',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号',
  `id_card` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证件号码',
  `school_stage` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学段，如小学/初中/高中',
  `political_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '政治面貌',
  `position_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `employee_status` tinyint(4) NULL DEFAULT 1 COMMENT '在职状态：1在职 2离职',
  `register_status` tinyint(4) NULL DEFAULT 0 COMMENT '注册状态：0待注册 1已通过 2已驳回 3待审核',
  `is_head_teacher` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否班主任：0否 1是，展示冗余，实际以绑定表为准',
  `create_user` bigint(20) NOT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  `regist_year` bigint(20) NULL DEFAULT NULL COMMENT '入职年份',
  `avatar_file_id` bigint(20) NULL DEFAULT NULL COMMENT '头像id',
  `audit_remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_teacher_user`(`user_id`) USING BTREE,
  INDEX `idx_as_teacher_employee_status`(`school_id`, `employee_status`) USING BTREE,
  INDEX `idx_as_teacher_register_status`(`school_id`, `register_status`) USING BTREE,
  INDEX `idx_as_teacher_head_teacher`(`school_id`, `is_head_teacher`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 398 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课后服务教师档案' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_as_teacher
-- ----------------------------

-- ----------------------------
-- Table structure for t_as_teacher_class
-- ----------------------------
DROP TABLE IF EXISTS `t_as_teacher_class`;
CREATE TABLE `t_as_teacher_class`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `teacher_id` bigint(20) NOT NULL COMMENT '教师ID，对应 t_as_teacher.id',
  `class_id` bigint(20) NOT NULL COMMENT '行政班ID，对应 t_educl_class.id',
  `bind_type` tinyint(4) NULL DEFAULT 1 COMMENT '绑定类型：1班主任 2任课关联',
  `start_date` date NULL DEFAULT NULL COMMENT '绑定开始日期',
  `end_date` date NULL DEFAULT NULL COMMENT '绑定结束日期',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_as_teacher_class_teacher`(`school_id`, `teacher_id`, `class_id`) USING BTREE,
  INDEX `idx_as_teacher_class_class`(`school_id`, `class_id`, `bind_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 228 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教师行政班级绑定' ROW_FORMAT = DYNAMIC;

