-- ----------------------------
-- Table structure for t_base_examine_record
-- ----------------------------
DROP TABLE IF EXISTS `t_base_examine_record`;
CREATE TABLE `t_base_examine_record`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `exam_type` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '审核来源',
  `exam_user` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `exam_advice` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '审核意见',
  `origin_id` bigint(20) NOT NULL COMMENT '被审核表主键',
  `exam_status` int(11) NULL DEFAULT 1 COMMENT '审核状态:1-已审核，2-待审核，3-已拒绝,4-撤回',
  `exam_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  `is_valid` int(11) NOT NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_base_examine_record_orid_index`(`origin_id`) USING BTREE,
  INDEX `t_base_examine_record_examtype_index`(`exam_type`) USING BTREE,
  INDEX `t_base_examine_record_examst_index`(`exam_status`) USING BTREE,
  INDEX `t_base_examine_record_examdt_index`(`exam_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '审核公共表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_base_examine_record
-- ----------------------------

-- ----------------------------
-- Table structure for t_base_file
-- ----------------------------
DROP TABLE IF EXISTS `t_base_file`;
CREATE TABLE `t_base_file`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `file_type` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文档类/图片类',
  `file_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '附件名称',
  `file_url` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '附件地址',
  `menu_type` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '菜单名称，来源',
  `oper_user` bigint(20) NOT NULL COMMENT '操作人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `upload_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `file_size` bigint(20) NULL DEFAULT NULL COMMENT '文件大小',
  `request_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'cos请求编号，外部云服务id/1-敏感文件，0-其他',
  `random` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'cos随机id',
  `expiration` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'cos密钥过期时间',
  `is_valid` int(11) NOT NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_base_file_file_type_index`(`file_type`) USING BTREE,
  INDEX `t_base_file_file_name_index`(`file_name`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '基础-上传附件表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_base_file
-- ----------------------------

-- ----------------------------
-- Table structure for t_base_template
-- ----------------------------
DROP TABLE IF EXISTS `t_base_template`;
CREATE TABLE `t_base_template`  (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT '主键',
  `template_code` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '编号',
  `template_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '模板名称',
  `menu_child_code` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '菜单子页面key',
  `menu` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '应用菜单',
  `enable` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否启用: 1-是 0-否',
  `attachment` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '文件',
  `create_user` bigint(20) NOT NULL COMMENT '创建人ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '最后更新人ID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_valid` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效（0-无效 1-有效）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `t_base_template_unique`(`template_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '基础管理-模板管理' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_base_template
-- ----------------------------

-- ----------------------------
-- Table structure for t_base_user
-- ----------------------------
DROP TABLE IF EXISTS `t_base_user`;
CREATE TABLE `t_base_user`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `login_name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录帐号',
  `login_pwd` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录密码',
  `actual_name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '员工名称',
  `nick_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '别名',
  `phone` varchar(15) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '手机号码',
  `id_card` varchar(18) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '身份证',
  `sex` bigint(10) NULL DEFAULT NULL COMMENT '性别,0-男，1-女',
  `mobile` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '固定电话',
  `birthday` date NULL DEFAULT NULL COMMENT '出生日期',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `department_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '部门id',
  `work_unit_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `is_leave` int(11) NULL DEFAULT 0 COMMENT '是否离职1是',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `approve_status` int(4) NULL DEFAULT 0 COMMENT '审批状态: 0-待审批 1-已通过 2-已驳回',
  `user_type` int(4) NULL DEFAULT NULL COMMENT '用户类型：0-管理员,1-学生(家长),2-教师,3-学校管理员,4-班主任,5-外部教师',
  `status` int(11) NULL DEFAULT 1 COMMENT '启用禁用，1-启用，0-禁用',
  `school_id` bigint(20) NULL DEFAULT NULL COMMENT '学校id,非超管账户都有值',
  `logo_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户头像地址',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效 1-有效 其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_base_user_astu_idx`(`approve_status`) USING BTREE,
  INDEX `t_base_user_lonm_idx`(`login_name`) USING BTREE,
  INDEX `t_base_user_phone_idx`(`phone`) USING BTREE,
  INDEX `t_base_user_usnm_idx`(`actual_name`) USING BTREE,
  INDEX `t_base_user_sch_idx`(`school_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5063 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '基础用户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_base_user
-- ----------------------------

-- ----------------------------
-- Table structure for t_content_advice
-- ----------------------------
DROP TABLE IF EXISTS `t_content_advice`;
CREATE TABLE `t_content_advice`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `source_type` int(10) NOT NULL COMMENT '来源：1-教师端、2-家长端、3-班主任',
  `advice_name` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '意见内容',
  `school_id` bigint(20) NOT NULL COMMENT '学校ID',
  `user_id` bigint(20) NOT NULL COMMENT '反馈用户ID',
  `category_id` bigint(20) NULL DEFAULT NULL COMMENT '分类，来源字典表',
  `author` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '反馈人',
  `mobile` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `status` int(10) NOT NULL COMMENT '状态,1-已处理，0-未处理',
  `file_url` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '附件地址,多个用,拼接',
  `create_user` bigint(20) NOT NULL COMMENT '创建人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '最后更新人ID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `is_valid` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效（0-无效 1-有效）',
  `check_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '意见正文',
  `audit_remark` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '处理意见',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_content_advice_sch_idx`(`school_id`) USING BTREE,
  INDEX `t_content_advice_pud_idx`(`create_time`) USING BTREE,
  INDEX `t_content_advice_stu_idx`(`status`) USING BTREE,
  INDEX `t_content_advice_usr_idx`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '意见反馈表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_content_advice
