  INDEX `idx_educl_event_school_type`(`school_id`, `event_type`) USING BTREE,
  INDEX `t_educl_calendar_event_name`(`school_id`, `event_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教务校历特殊日期/事件' ROW_FORMAT = DYNAMIC;

