-- ----------------------------
-- Table structure for t_educl_grade
-- ----------------------------
DROP TABLE IF EXISTS `t_educl_grade`;
CREATE TABLE `t_educl_grade`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `grade_code` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年级编码，同一学校内唯一',
  `school_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阶段：1-小学/2-初中/3-高中',
  `grade_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '年级名称，如一年级、七年级',
  `director_user_id` bigint(20) NULL DEFAULT NULL COMMENT '年级主任账号，对应 t_as_teacher.id',
  `director_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年级主任名称，便于导入展示',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `sort_no` int(11) NULL DEFAULT 0 COMMENT '排序号，值越小越靠前',
  `create_user` bigint(20) NOT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `is_valid` tinyint(4) NOT NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_educl_grade_code`(`school_id`, `grade_code`) USING BTREE,
  INDEX `idx_educl_grade_stage`(`school_id`, `school_stage`) USING BTREE,
  INDEX `t_educl_grade_name`(`school_id`, `grade_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教务年级' ROW_FORMAT = DYNAMIC;

