-- Records of t_educl_grade
-- ----------------------------

-- ----------------------------
-- Table structure for t_educl_major
-- ----------------------------
DROP TABLE IF EXISTS `t_educl_major`;
CREATE TABLE `t_educl_major`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `major_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '专业名',
  `major_code` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '专业编号',
  `site_id` bigint(20) NOT NULL COMMENT '院系表主键',
  `major_type` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '专业类',
