  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  `degree` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '学历层次：1-中专 2-大专 3-本科 4-硕士研究生 5-博士研究生',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_educl_major_major_code_index`(`major_code`) USING BTREE,
  INDEX `t_educl_major_major_name_index`(`major_name`) USING BTREE,
  INDEX `t_educl_major_site_id_index`(`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '教务-专业表' ROW_FORMAT = DYNAMIC;

