  `site_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '院系/站点名称',
  `director_name` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '负责人姓名',
  `director_phone` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '负责人电话',
  `site_introduce` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '院系介绍',
