-- ----------------------------
-- Table structure for t_educl_term
-- ----------------------------
DROP TABLE IF EXISTS `t_educl_term`;
CREATE TABLE `t_educl_term`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint(20) NOT NULL COMMENT '所属学校，对应 t_school_manage.id',
  `term_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '学期编码/序号，同一学校内唯一',
  `term_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '学期名称，如2024-2025学年第一学期',
  `school_year` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学年，如2023-2024学年',
  `term_type` tinyint(4) NOT NULL COMMENT '学期类型：1第一学期 2第二学期 3其他',
  `start_date` date NOT NULL COMMENT '学期开始日期',
  `end_date` date NOT NULL COMMENT '学期结束日期',
  `total_weeks` int(11) NULL DEFAULT NULL COMMENT '总周数',
  `term_status` tinyint(4) NULL DEFAULT 0 COMMENT '学期状态：1启用 0停用',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人，对应 t_base_user.id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人，对应 t_base_user.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `is_valid` tinyint(4) NULL DEFAULT 1 COMMENT '有效标记：1有效 0无效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_educl_term_code`(`school_id`, `term_code`) USING BTREE,
  INDEX `idx_educl_term_date`(`school_id`, `start_date`, `end_date`) USING BTREE,
  INDEX `idx_educl_term_status`(`school_id`, `term_status`) USING BTREE,
  INDEX `t_educl_term_name`(`school_id`, `term_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教务学期/校历' ROW_FORMAT = DYNAMIC;

