CREATE TABLE `t_instructions`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `context` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `oper_type` int(11) NOT NULL COMMENT '操作指南类型,1-操作类，2-体验类，3-其他类',
  `oper_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '操作指南名称',
  `oper_role` int(11) NOT NULL COMMENT '操作指南面向角色，1-教师，2-学生、3-管理员',
  `inst_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作指南附件',
  `oper_status` int(11) NOT NULL COMMENT '操作指南状态，1-启用，2-禁用',
  `create_user` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `source_context` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容搜索',
  `is_valid` int(11) NULL DEFAULT 0 COMMENT '是否有效，1-有效，0-无效',
  PRIMARY KEY (`id`) USING BTREE
