  `is_show` int(11) NULL DEFAULT NULL COMMENT '是否展示 1-是，其他否',
  `sort` int(11) NULL DEFAULT NULL COMMENT '排序',
  `photo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文章图片路径',
  `school_id` bigint(20) NULL DEFAULT NULL COMMENT '文章图片路径',
  `is_outside` int(11) NULL DEFAULT NULL COMMENT '是否外部',
  `target_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标链接',
  `link_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '链接',
