  INDEX `idx_is_show`(`is_show`) USING BTREE,
  INDEX `idx_is_valid`(`is_valid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15692642027384 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Portal 文章管理表' ROW_FORMAT = DYNAMIC;

