  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `cul_num` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '编号',
  `cul_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '轮播图名称',
