  `sort` int(11) NULL DEFAULT NULL COMMENT '排序',
  `cul_url_id` bigint(20) NULL DEFAULT NULL COMMENT '附件表的地址id',
  `cul_desc` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '轮播图描述',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '启用状态，1-启用，其他禁用',
  `create_user` bigint(20) NOT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '修改人',
  `publish_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_valid` int(11) NULL DEFAULT 0 COMMENT '是否有效，1-有效，其他无效',
