  INDEX `t_portal_carousel_cul_name_index`(`cul_name`) USING BTREE,
  INDEX `t_portal_carousel_publish_date_index`(`publish_date`) USING BTREE,
  INDEX `t_portal_carousel_status_index`(`status`) USING BTREE
