-- ----------------------------
-- Table structure for t_portal_protocol
-- ----------------------------
DROP TABLE IF EXISTS `t_portal_protocol`;
CREATE TABLE `t_portal_protocol`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `protocol_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '协议名称',
  `protocol_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '协议编号',
  `protocol_type` int(11) NULL DEFAULT NULL COMMENT '协议类型 1-用户协议 2-隐私政策',
  `version_num` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '版本号',
  `is_enable` int(11) NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是',
  `protocol_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '协议内容',
  `use_cases` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '使用场景（多个） 1-用户注册 2-捐赠模块 3-企业赞助 4-社群管理 5-企业认证',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` bigint(20) NOT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_portal_protocol_name_index`(`protocol_name`) USING BTREE,
  INDEX `t_portal_protocol_code_index`(`protocol_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14517938481637 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '基础管理-协议管理' ROW_FORMAT = DYNAMIC;

