-- ----------------------------
-- Table structure for t_privilege_info
-- ----------------------------
DROP TABLE IF EXISTS `t_privilege_info`;
CREATE TABLE `t_privilege_info`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '功能权限表主键id',
  `type` tinyint(4) NOT NULL COMMENT '1.菜单 2.功能点',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '菜单名称',
  `key` varchar(60) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '路由name 英文关键字',
  `url` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '路由path/type=3为API接口',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `parent_key` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父级key',
  `menu_source` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '菜单服务端：PTPC/XCX/GLD',
  `icon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '图标',
  `is_show` int(11) NULL DEFAULT NULL COMMENT '是否显示，1-显示，其他不显示',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NOT NULL COMMENT '创建人id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '修改人id',
  `is_valid` int(11) NOT NULL DEFAULT 1 COMMENT '是否有效，1-有效，0-无效',
  `meta_order` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '前端使用字段',
  `meta_active_path` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '前端活动地址',
  `meta_title` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '前端标题',
  `component` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '前端路径',
  `hide_in_menu` int(10) NULL DEFAULT NULL COMMENT '前端是否隐藏,1-true,0-false',
  `redirect` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '前端重定向地址',
  `description` varchar(252) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '菜单描述',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `key`(`key`) USING BTREE,
  INDEX `t_privilege_info_typ_idx`(`type`) USING BTREE,
  INDEX `t_privilege_info_pky_idx`(`parent_key`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 464 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统权限功能表' ROW_FORMAT = DYNAMIC;

