-- ----------------------------
-- Table structure for t_role
-- ----------------------------
DROP TABLE IF EXISTS `t_role`;
CREATE TABLE `t_role`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '角色编码',
  `role_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '角色名称',
  `role_type` bigint(20) NULL DEFAULT 2 COMMENT '0-管理员，1-校友学生，2-校友教职工，3-学校管理员，4-外部单位(企业管理员等)',
  `status` int(11) NOT NULL DEFAULT 1 COMMENT '1启用 2禁用',
  `remark` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '角色描述',
  `create_user` bigint(20) NOT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_valid` int(1) NULL DEFAULT 1 COMMENT '是否有效，1-有效默认，0 无效',
  `is_school` int(11) NULL DEFAULT 0 COMMENT '是否是跟学校有关的角色，1-是，0-否',
  `sort` int(10) NULL DEFAULT NULL COMMENT '排序，从小到大排序',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_role_code_index`(`code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '角色表' ROW_FORMAT = DYNAMIC;

