  INDEX `t_role_privilege_urid_idx`(`role_id`) USING BTREE,
  INDEX `t_role_privilege_prk_idx`(`privilege_key`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 120295 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色权限功能表' ROW_FORMAT = DYNAMIC;

