-- Table structure for t_role_user
-- ----------------------------
DROP TABLE IF EXISTS `t_role_user`;
CREATE TABLE `t_role_user`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL COMMENT '角色id',
  `user_id` int(11) NOT NULL COMMENT '员工id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '修改人id',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_role_user_rid_idx`(`role_id`) USING BTREE,
  INDEX `t_role_user_uid_idx`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5238 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色员工功能表' ROW_FORMAT = DYNAMIC;

