-- ----------------------------
-- Table structure for t_school_manage
-- ----------------------------
DROP TABLE IF EXISTS `t_school_manage`;
CREATE TABLE `t_school_manage`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学校名称',
  `school_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学校代码',
  `school_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '1-大学，2-职业学院，3-中学、4-小学',
  `manager_id` bigint(20) NOT NULL COMMENT '管理员ID',
  `manager_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管理员姓名',
  `manager_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管理员手机号',
  `school_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学校logo图片路径',
  `school_honor` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学校荣誉录',
  `school_process` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学校发展历程',
  `school_brief` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学校简介',
  `school_address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学校位置/来校路线',
  `create_user` bigint(20) NOT NULL COMMENT '创建人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '最后更新人ID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `is_valid` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效（0-无效 1-有效）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_school_type`(`school_type`) USING BTREE,
  INDEX `idx_is_valid`(`is_valid`) USING BTREE,
  INDEX `idx_manager_id`(`school_code`) USING BTREE,
  INDEX `idx_school_schoolname_id`(`school_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14166527992676 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '学校信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_school_manage
-- ----------------------------

-- ----------------------------
-- Table structure for t_system_change_config
-- ----------------------------
DROP TABLE IF EXISTS `t_system_change_config`;
CREATE TABLE `t_system_change_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `config_type` int(1) NOT NULL COMMENT '1:待办警告，2-通知规则，3-日志监控，4-安全设置',
  `config_key` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则key',
  `config_val` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则值',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NOT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效，1-有效默认，0 无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `t_system_change_config_cfk_idx`(`config_key`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统全局配置表' ROW_FORMAT = DYNAMIC;

