CREATE TABLE `t_teacher_subject`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '关联ID',
  `teacher_id` bigint(20) UNSIGNED NOT NULL COMMENT '教师ID（关联教师管理表）',
  `subject_id` bigint(20) UNSIGNED NOT NULL COMMENT '学科ID（关联 t_as_subject）',
  `school_id` bigint(20) UNSIGNED NOT NULL COMMENT '学校ID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` bigint(20) NOT NULL COMMENT '创建人',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `is_valid` int(11) NULL DEFAULT 1 COMMENT '是否有效，1-有效，其他无效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_subject_id`(`subject_id`) USING BTREE,
  INDEX `idx_teacher_id`(`teacher_id`) USING BTREE
